package com.mediconnect.clinicalnote.application;
import java.util.*; import com.mediconnect.appointment.application.AppointmentService; import com.mediconnect.appointment.domain.AppointmentEntity; import com.mediconnect.clinicalnote.api.*; import com.mediconnect.clinicalnote.domain.ClinicalNoteDocument; import com.mediconnect.clinicalnote.infrastructure.*; import com.mediconnect.patient.domain.PatientEntity; import com.mediconnect.patient.infrastructure.PatientRepository; import com.mediconnect.shared.exception.ResourceNotFoundException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ClinicalNoteService { private final ClinicalNoteRepository repository; private final ClinicalNoteMapper mapper; private final AppointmentService appointmentService; private final PatientRepository patientRepository; public ClinicalNoteService(ClinicalNoteRepository repository,ClinicalNoteMapper mapper,AppointmentService appointmentService,PatientRepository patientRepository){this.repository=repository;this.mapper=mapper;this.appointmentService=appointmentService;this.patientRepository=patientRepository;} @PreAuthorize("hasRole('DOCTOR')") @Transactional public ClinicalNoteResponse createForAssignedAppointment(String doctorEmail,UUID appointmentId,ClinicalNoteRequest request){AppointmentEntity appointment=appointmentService.requireAssignedDoctor(doctorEmail,appointmentId);ClinicalNoteDocument document=new ClinicalNoteDocument(appointment.getId(),appointment.getPatient().getId(),appointment.getDoctor().getId(),request.content().trim());return mapper.toResponse(repository.save(document));} @PreAuthorize("hasRole('PATIENT')") public List<ClinicalNoteResponse> listForPatient(String patientEmail){PatientEntity patient=patientRepository.findByUserEmailIgnoreCase(patientEmail).orElseThrow(()->new ResourceNotFoundException("Patient profile not found."));return repository.findByPatientIdOrderByCreatedAtDesc(patient.getId()).stream().map(mapper::toResponse).toList();} }
